export function getOfflineReplay(strategy: string, period: string = "full"): BacktestResponse {
  const normStrat = strategy === "buy_and_hold" ? "bh_and_hold" : strategy;
  const key = normStrat + "_" + period;
  if (VERIFIED_REPLAYS[key]) {
    return VERIFIED_REPLAYS[key];
  }
  // Try fallback by strategy
  const fallbackKey = normStrat + "_full";
  if (VERIFIED_REPLAYS[fallbackKey]) {
    return VERIFIED_REPLAYS[fallbackKey];
  }
  // Default fallback
  return VERIFIED_REPLAYS["sma_crossover_full"] || Object.values(VERIFIED_REPLAYS)[0];
}
